def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            opp_c += 1
    opp_d = n - opp_c

    w10 = 10 if n >= 10 else n
    recent_c = 0
    for i in range(n - w10, n):
        if history[i][1] == 'C':
            recent_c += 1
    recent_opp = recent_c / float(w10)

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    c_after_d = 0
    d_after_d = 0
    start = 1
    if n > 21:
        start = n - 20
    for i in range(start, n):
        if history[i - 1][0] == 'D':
            if history[i][1] == 'C':
                c_after_d += 1
            else:
                d_after_d += 1

    unprov = 0
    startu = 0 if n <= 10 else n - 10
    for i in range(startu, n):
        if history[i][1] == 'D':
            if i == 0 or history[i - 1][0] == 'C':
                unprov += 1

    rounds_left = 100 - n

    if opp_c == 0:
        return 'D'

    if recent_opp <= 0.30 and unprov >= 1:
        return 'D'
    if unprov >= 3 and recent_opp < 0.75:
        return 'D'
    if opp_d_streak >= 3 and recent_opp <= 0.55:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if recent_opp >= 0.50 or opp_d_streak <= 1:
                return 'C'
            return 'D'

        if n >= 2 and history[-2][0] == 'D':
            if opp_d_streak <= 2 and recent_opp >= 0.50:
                return 'C'
            if opp_d_streak >= 3 and recent_opp < 0.65:
                return 'D'
            return 'C'

        return 'D'

    if last_me == 'D':
        if opp_d == 0 and recent_opp >= 0.95 and rounds_left > 5:
            return 'D'
        if d_after_d == 0 and c_after_d >= 3 and recent_opp >= 0.95 and rounds_left > 20:
            return 'D'
        return 'C'

    if opp_d == 0 and n >= 10 and recent_opp >= 0.95 and rounds_left > 10:
        if rng.random() < 0.08:
            return 'D'

    if opp_d <= 3 and d_after_d == 0 and c_after_d >= 2 and recent_opp >= 0.90 and n >= 15 and rounds_left > 20:
        if rng.random() < 0.04:
            return 'D'

    return 'C'
